// pubspec.yaml: permission_handler: ^11.3.0
import 'package:permission_handler/permission_handler.dart';

// ────── Reusable helper with pre-prompt explainer ──────
Future<bool> ensurePermission(BuildContext context, Permission p, {
  required String title, required String rationale,
}) async {
  var status = await p.status;
  if (status.isGranted || status.isLimited) return true;

  if (status.isPermanentlyDenied) {
    // Only path: user must open settings
    final go = await showDialog<bool>(context: context, builder: (_) => AlertDialog(
      title: Text(title),
      content: Text('$rationale\nOpen Settings to enable.'),
      actions: [
        TextButton(onPressed: () => Navigator.pop(context, false), child: const Text('Cancel')),
        FilledButton(onPressed: () => Navigator.pop(context, true), child: const Text('Open Settings')),
      ],
    ));
    if (go == true) await openAppSettings();
    return false;
  }

  // Show explainer BEFORE system prompt — dramatically improves acceptance
  final proceed = await showDialog<bool>(context: context, builder: (_) => AlertDialog(
    title: Text(title),
    content: Text(rationale),
    actions: [
      TextButton(onPressed: () => Navigator.pop(context, false), child: const Text('Not now')),
      FilledButton(onPressed: () => Navigator.pop(context, true), child: const Text('Continue')),
    ],
  ));
  if (proceed != true) return false;

  status = await p.request();
  return status.isGranted || status.isLimited;
}

// ────── Usage in a widget ──────
Future<void> _scanBarcode() async {
  final ok = await ensurePermission(context, Permission.camera,
    title: 'Camera access',
    rationale: 'We use the camera to scan barcodes on products.');
  if (!ok) return;
  // proceed to scan
}

// ────── Android 13+ media split ──────
final photosOk = await Permission.photos.request();      // iOS photo lib
final imagesOk = await Permission.photosAddOnly.request(); // iOS add-only
// On Android 13+, images / videos / audio each have separate permissions
final androidImages = await Permission.photos.request();  // maps to READ_MEDIA_IMAGES

// ────── Bluetooth (Android 12+ split) ──────
final btScan = await Permission.bluetoothScan.request();
final btConnect = await Permission.bluetoothConnect.request();
final btAdvertise = await Permission.bluetoothAdvertise.request();

// ────── Batched request ──────
final statuses = await [Permission.camera, Permission.microphone, Permission.location].request();
for (final e in statuses.entries) print('${e.key} = ${e.value}');
